<script setup lang="ts">
import { ref, watch } from 'vue';
import { watchToast } from './toast';
const props=defineProps<{user:{username:string;nickname:string|null;mobile:string;avatar:string|null};token:string}>();
const emit=defineEmits<{updated:[user:{username:string;nickname:string|null;mobile:string;avatar:string|null}]}>();
const fileInput=ref<HTMLInputElement|null>(null), avatarBusy=ref(false);
async function updateAvatar(avatar:string|null){avatarBusy.value=true;error.value='';notice.value='';try{const response=await fetch('/api/v1/users/me/avatar',{method:'PUT',headers:{'Content-Type':'application/json',Authorization:`Bearer ${props.token}`},body:JSON.stringify({avatar})});const data=await response.json();if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:'头像保存失败。');emit('updated',data);notice.value=avatar?'头像已更新。':'头像已移除。';}catch(e){error.value=(e as Error).message||'无法连接服务。';}finally{avatarBusy.value=false;}}
async function chooseAvatar(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];input.value='';if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){error.value='请选择不超过 5 MB 的 JPG、PNG 或 WebP 图片。';return;}avatarBusy.value=true;const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const size=Math.min(image.naturalWidth,image.naturalHeight);if(!size)throw new Error('无法读取图片。');const canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;const context=canvas.getContext('2d');if(!context)throw new Error('无法处理图片。');context.fillStyle='#fff';context.fillRect(0,0,256,256);context.drawImage(image,(image.naturalWidth-size)/2,(image.naturalHeight-size)/2,size,size,0,0,256,256);let avatar=canvas.toDataURL('image/jpeg',0.8);if(avatar.length>48000)avatar=canvas.toDataURL('image/jpeg',0.5);if(avatar.length>48000)throw new Error('图片处理失败，请选择其他图片。');await updateAvatar(avatar);}catch(e){error.value=(e as Error).message||'图片读取失败。';}finally{URL.revokeObjectURL(url);avatarBusy.value=false;}}
const nickname=ref(props.user.nickname||''),error=ref(''),notice=ref(''),busy=ref(false);
watchToast(error, 'error'); watchToast(notice, 'success');
watch(()=>props.user.nickname, value=>nickname.value=value||'');
async function save(){busy.value=true;error.value='';notice.value='';try{const response=await fetch('/api/v1/users/me',{method:'PATCH',headers:{'Content-Type':'application/json',Authorization:`Bearer ${props.token}`},body:JSON.stringify({nickname:nickname.value.trim()||null})});const data=await response.json();if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:'保存失败，请检查输入。');emit('updated',data);notice.value='昵称已保存。';}catch(e){error.value=(e as Error).message||'无法连接服务。';}finally{busy.value=false;}}
</script>
<template><main class="profile"><h1>个人中心</h1><section><h2>基本信息</h2><div class="avatar-row"><div class="profile-avatar"><img v-if="user.avatar" :src="user.avatar" alt="当前头像"><span v-else>{{ (user.nickname || user.username).slice(0, 1) }}</span></div><div class="avatar-actions"><input ref="fileInput" class="file-input" type="file" accept="image/jpeg,image/png,image/webp" @change="chooseAvatar"><button type="button" :disabled="avatarBusy" @click="fileInput?.click()">{{ avatarBusy ? '处理中…' : user.avatar ? '更换头像' : '添加头像' }}</button><button v-if="user.avatar" type="button" class="remove-avatar" :disabled="avatarBusy" @click="updateAvatar(null)">移除头像</button></div></div><form @submit.prevent="save"><label>登录账号<input :value="user.username" disabled></label><label>手机号<input :value="user.mobile" disabled></label><label>昵称<input v-model="nickname" maxlength="80" placeholder="请输入昵称"></label><button :disabled="busy">{{ busy?'保存中…':'保存修改' }}</button></form></section></main></template>
<style scoped>.profile{padding:36px 40px;max-width:900px}.profile h1{font-size:26px;margin:0}.profile>p{color:#728297;font-size:13px;margin:9px 0 24px}.profile section{background:white;border:1px solid #e5e9ef;border-radius:8px;padding:24px}.profile h2{font-size:16px;margin:0 0 24px}.profile form{max-width:420px}.profile label{display:block;font-size:13px;margin:16px 0;color:#42546a}.profile input{display:block;width:100%;padding:10px;margin-top:8px;border:1px solid #dbe3ec;border-radius:5px;font:inherit}.profile input:disabled{background:#f5f7fa;color:#8190a0}.profile button{background:#0073e6;border:0;color:white;padding:10px 18px;border-radius:5px;cursor:pointer}.error{color:#ba3e3e}.notice{color:#32845a}button:focus-visible,input:focus-visible{outline:2px solid #0073e6;outline-offset:2px}@media(max-width:700px){.profile{padding:24px 16px}}
.profile{flex:1;max-width:none;min-height:0;padding:20px;background:#f0f2f5}.profile>h1,.profile>p{margin:0;background:#fff;padding:20px 20px 0;font-size:18px}.profile>p{padding:8px 20px 20px;font-size:13px;color:#8290a3}.profile section{margin-top:14px;min-height:320px;border:0;border-radius:0 0 6px 6px;padding:24px 20px}.profile h2{color:#172233;font-size:18px}.profile input{border-color:#dce3ed;border-radius:6px;box-sizing:border-box}.profile button{background:#5267ff;border-radius:5px}.profile button:hover{background:#4054ed}.profile button:focus-visible,.profile input:focus-visible{outline-color:#5267ff}@media(max-width:700px){.profile{padding:12px}.profile section{padding:20px}}

.profile input,.profile button{box-sizing:border-box;height:40px;font-size:14px}.profile button{min-width:72px;padding:0 16px;display:inline-flex;align-items:center;justify-content:center;line-height:1}


.profile{padding:8px}.profile>h1{border:2px solid #d8e0ec;border-bottom:0}.profile>p{border:2px solid #d8e0ec;border-top:0}.profile section{margin-top:8px;border:2px solid #d8e0ec}@media(max-width:700px){.profile{padding:6px}.profile section{margin-top:6px}}


.profile{padding:2px}.profile section{margin-top:2px;border-radius:0}@media(max-width:700px){.profile{padding:2px}.profile section{margin-top:2px}}

.profile>h1{border-bottom:2px solid #d8e0ec;padding:20px}
.avatar-row{display:flex;align-items:center;gap:20px;margin:0 0 24px}.profile-avatar{width:80px;height:80px;flex:none;display:grid;place-items:center;border-radius:50%;background:#e7ebff;color:#5267ff;font-size:28px;overflow:hidden}.profile-avatar img{width:100%;height:100%;object-fit:cover}.avatar-actions{display:flex;gap:10px;flex-wrap:wrap}.profile .file-input{display:none}.profile .remove-avatar{background:#fff;border:1px solid #dce3ed;color:#334155}.profile .remove-avatar:hover{background:#f4f5ff;color:#5267ff}.profile button:disabled{opacity:.5;cursor:not-allowed}
</style>
